//! 🧪️ Actual executor-issued original signal leases keep thread wakes, stale generations and paid closure distinct.
use super::*;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn executor_original_typed_wake_keeps_thread_safe_generation_signal_and_physical_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};
 for final_signal in [false,true]{let executor=ColdFutureExecutor::new();let id=executor.spawn(std::future::pending()).unwrap();assert_eq!(executor.poll_one(id),TaskPoll::Pending);let(waker,birth)=observe(||executor.waker_for(id));let pointer=waker.data();let quote=original_worker_wake_admission_demands::<WakerData>().unwrap();let copy=quote.copy_bytes+size_of::<Arc<WakerData>>();
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:copy-1,..grant},RetainedCloneGrant{maximum_capacity_bytes:quote.capacity_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(admitted,heap)=observe(||admit_original_executor_wake(&waker,denied).unwrap());assert!(admitted.is_none());assert_eq!(heap,(0,0));assert_eq!(waker.data(),pointer);}
 let((mut owner,receipt),heap)=observe(||admit_original_executor_wake(&waker,grant).unwrap().unwrap());assert!(receipt.fits(grant));assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),heap);let mut born=birth.0+heap.0;let mut released=birth.1+heap.1;
 let(_,heap)=observe(||owner.wake_by_ref());assert_eq!(heap,(0,0));assert!(executor.has_ready());assert_eq!(executor.poll_one(id),TaskPoll::Pending);
 let threaded=waker.clone();std::thread::spawn(move||threaded.wake_by_ref()).join().unwrap();assert!(executor.has_ready());assert_eq!(executor.poll_one(id),TaskPoll::Pending);
 if final_signal{drop(executor.detach(id).unwrap());assert!(!executor.has_ready());let(_,heap)=observe(||waker.wake_by_ref());assert_eq!(heap,(0,0));assert!(!executor.has_ready());}
 let(step,heap)=observe(||owner.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);born+=heap.0;released+=heap.1;
 let(step,heap)=observe(||owner.close_step(grant).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(waker.data(),pointer);
 let(_,heap)=observe(||drop(waker));assert_eq!(heap,(0,0));let mut turns=0;
 while !owner.terminal_is_empty(){turns+=1;assert!(turns<128);let(demand,heap)=observe(||owner.retirement_demands(grant.maximum_copy_bytes).unwrap());assert_eq!(heap,(0,0));
 for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}),(demand.depth>0).then_some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant})].into_iter().flatten(){let(step,heap)=observe(||owner.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}
 let(step,heap)=observe(||owner.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);born+=heap.0;released+=heap.1;}
 let frame=owner.frame_release_bytes();let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,frame));released+=heap.1;assert_eq!(released,born+if final_signal{semio_framework_value::shared_retirement_allocation_bytes::<ExecutorWakeSignal>()}else{0});
 eprintln!("[DEBUG] actual executor original stdWaker pointer denied/full4096 retained worker-thread wake original atomic signal stale detached generation ignored finalSignal={final_signal} typed turns={turns} physical={released} original preexisting Signal separately conserved scheduler/Future release excluded");}
 struct Foreign;impl std::task::Wake for Foreign{fn wake(self:Arc<Self>){}}
 let foreign=Waker::from(Arc::new(Foreign));let(result,heap)=observe(||admit_original_executor_wake(&foreign,grant));assert!(matches!(result,Err(error)if error.kind==ValueRefusalKind::UnsupportedOwner));assert_eq!(heap,(0,0));
}
